/**
 * Inverse Kinematics
 *
 * bpy.types.KinematicConstraint
 */
export interface KinematicConstraint extends R.Constraint {
  /** Target object */
  get target(): H.Ptr<R.Object>;
  set target(v: R.Object | null);
  /** Armature bone, mesh or lattice vertex group, ... Default: "". */
  get subtarget(): H.Ref<string>;
  set subtarget(v: H.In<string>);
  /** Maximum number of solving iterations Range: 0 to 10000. Default: 0. */
  get iterations(): H.Ref<number>;
  set iterations(v: H.In<number>);
  /** Object for pole rotation */
  get pole_target(): H.Ptr<R.Object>;
  set pole_target(v: R.Object | null);
  /** Pole Sub-Target Default: "". */
  get pole_subtarget(): H.Ref<string>;
  set pole_subtarget(v: H.In<string>);
  /** Pole rotation offset Range: -3.1415927410125732 to 3.1415927410125732. Default: 0.0. */
  get pole_angle(): H.Ref<number>;
  set pole_angle(v: H.In<number>);
  /** For Tree-IK: Weight of position control for this target Range: 0.009999999776482582 to 1. Default: 0.0. */
  get weight(): H.Ref<number>;
  set weight(v: H.In<number>);
  /** For Tree-IK: Weight of orientation control for this target Range: 0.009999999776482582 to 1. Default: 0.0. */
  get orient_weight(): H.Ref<number>;
  set orient_weight(v: H.In<number>);
  /** How many bones are included in the IK effect - 0 uses all bones Range: 0 to 255. Default: 0. */
  get chain_count(): H.Ref<number>;
  set chain_count(v: H.In<number>);
  /** Include bone's tail as last element in chain Default: False. */
  get use_tail(): H.Ref<boolean>;
  set use_tail(v: H.In<boolean>);
  /**
   * Constraint axis Lock options relative to Bone or Target reference Default: 'BONE'.
   * - `BONE`: Bone
   * - `TARGET`: Target
   */
  get reference_axis(): H.Ref<"BONE" | "TARGET">;
  set reference_axis(v: H.In<"BONE" | "TARGET">);
  /** Chain follows position of target Default: False. */
  get use_location(): H.Ref<boolean>;
  set use_location(v: H.In<boolean>);
  /** Constraint position along X axis Default: True. */
  get lock_location_x(): H.Ref<boolean>;
  set lock_location_x(v: H.In<boolean>);
  /** Constraint position along Y axis Default: True. */
  get lock_location_y(): H.Ref<boolean>;
  set lock_location_y(v: H.In<boolean>);
  /** Constraint position along Z axis Default: True. */
  get lock_location_z(): H.Ref<boolean>;
  set lock_location_z(v: H.In<boolean>);
  /** Chain follows rotation of target Default: False. */
  get use_rotation(): H.Ref<boolean>;
  set use_rotation(v: H.In<boolean>);
  /** Constraint rotation along X axis Default: True. */
  get lock_rotation_x(): H.Ref<boolean>;
  set lock_rotation_x(v: H.In<boolean>);
  /** Constraint rotation along Y axis Default: True. */
  get lock_rotation_y(): H.Ref<boolean>;
  set lock_rotation_y(v: H.In<boolean>);
  /** Constraint rotation along Z axis Default: True. */
  get lock_rotation_z(): H.Ref<boolean>;
  set lock_rotation_z(v: H.In<boolean>);
  /** Enable IK Stretching Default: False. */
  get use_stretch(): H.Ref<boolean>;
  set use_stretch(v: H.In<boolean>);
  /**
   * IK Type Default: 'COPY_POSE'.
   * - `COPY_POSE`: Copy Pose
   * - `DISTANCE`: Distance
   */
  get ik_type(): H.Ref<"COPY_POSE" | "DISTANCE">;
  set ik_type(v: H.In<"COPY_POSE" | "DISTANCE">);
  /**
   * Distances in relation to sphere of influence to allow Default: 'LIMITDIST_INSIDE'.
   * - `LIMITDIST_INSIDE`: Inside (The object is constrained inside a virtual sphere around the target object, with a radius defined by the limit distance)
   * - `LIMITDIST_OUTSIDE`: Outside (The object is constrained outside a virtual sphere around the target object, with a radius defined by the limit distance)
   * - `LIMITDIST_ONSURFACE`: On Surface (The object is constrained on the surface of a virtual sphere around the target object, with a radius defined by the limit distance)
   */
  get limit_mode(): H.Ref<"LIMITDIST_INSIDE" | "LIMITDIST_OUTSIDE" | "LIMITDIST_ONSURFACE">;
  set limit_mode(v: H.In<"LIMITDIST_INSIDE" | "LIMITDIST_OUTSIDE" | "LIMITDIST_ONSURFACE">);
  /** Radius of limiting sphere Range: 0 to 100. Default: 0.0. */
  get distance(): H.Ref<number>;
  set distance(v: H.In<number>);
}
